#include <bits/stdc++.h>using namespace std;#define int long long char graph[501][501];bool visited[501][501];vector<pair<int, int>> connected;int connected_size = 0;int dot_count = 0;int dir_x[] = {-1, 1, 0, 0};int dir_y[] = {0, 0, 1, -1}; void dfs(int i, int j, int n, int m) {    if (i < 1 || i > n || j < 1 || j > m || visited[i][j] ||        graph[i][j] == '#') {        return;    }     visited[i][j] = true;     connected.push_back({i, j});    connected_size += 1;     for (int c = 0; c < 4; c++) {        dfs(i + dir_x[c], j + dir_y[c], n, m);    }} int32_t main() {    int n, m, k;    cin >> n >> m >> k;     int start_x = -1, start_y = -1;    for (int i = 1; i <= n; i++) {        for (int j = 1; j <= m; j++) {            cin >> graph[i][j];            visited[i][j] = false;            dot_count += (graph[i][j] == '.');            if (graph[i][j] == '.' && start_x == -1) {                start_x = i;                start_y = j;            }        }    }     if (start_x != -1) {        dfs(start_x, start_y, n, m);    }    int total_empty = connected.size();    for (int i = total_empty - 1; i >= total_empty - k; i--) {        int r = connected[i].first;        int c = connected[i].second;        graph[r][c] = 'X';    }     for (int i = 1; i <= n; i++) {        for (int j = 1; j <= m; j++) {            cout << graph[i][j];        }        cout << "\n";    }     return 0;}